package com.parion.aidat;

import android.content.*;
import android.database.Cursor;
import android.database.sqlite.*;
import java.util.*;

/** v4 local cache. No athlete/payment seed data is bundled in the APK. */
public class DbHelper extends SQLiteOpenHelper {
    static final String DB="parion_spor_okulu.db";
    static final int VER=5;
    private Context ctx;

    public DbHelper(Context c){super(c,DB,null,VER);ctx=c.getApplicationContext();}

    @Override public void onCreate(SQLiteDatabase d){
        d.execSQL("CREATE TABLE athletes(id INTEGER PRIMARY KEY,seq INTEGER,birthYear INTEGER,birthDate TEXT,name TEXT,category TEXT,status TEXT,monthlyFee INTEGER,sibling TEXT,tshirtQty INTEGER,tshirtPaid INTEGER,tracksuitQty INTEGER,tracksuitPaid INTEGER,notes TEXT,phone TEXT,motherName TEXT,motherPhone TEXT,fatherName TEXT,fatherPhone TEXT,startDate TEXT,endDate TEXT,restartDate TEXT,photo TEXT,tckn TEXT,summerCall INTEGER NOT NULL DEFAULT 0,winterCall INTEGER NOT NULL DEFAULT 0,deletedAt TEXT,deletedPrevStatus TEXT)");
        d.execSQL("CREATE TABLE payments(id INTEGER PRIMARY KEY AUTOINCREMENT,athleteId INTEGER,year INTEGER,month INTEGER,marker TEXT,amount INTEGER,UNIQUE(athleteId,year,month))");
        createFeeHistory(d);createMaterialTables(d);createSyncTables(d);createRecentPayments(d);createRestartPeriods(d);
    }
    private void createFeeHistory(SQLiteDatabase d){d.execSQL("CREATE TABLE IF NOT EXISTS fee_history(id INTEGER PRIMARY KEY AUTOINCREMENT,athleteId INTEGER,year INTEGER,effectiveMonth INTEGER,fee INTEGER,UNIQUE(athleteId,year,effectiveMonth))");}
    private void createMaterialTables(SQLiteDatabase d){d.execSQL("CREATE TABLE IF NOT EXISTS material_products(name TEXT PRIMARY KEY,currentPrice INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,cloudId TEXT)");d.execSQL("CREATE TABLE IF NOT EXISTS material_transactions(id INTEGER PRIMARY KEY AUTOINCREMENT,cloudId TEXT UNIQUE,athleteId INTEGER NOT NULL,product TEXT NOT NULL,qty INTEGER NOT NULL,unitPrice INTEGER NOT NULL,total INTEGER NOT NULL,paidAmount INTEGER NOT NULL DEFAULT 0,issuedDate TEXT NOT NULL,paymentDate TEXT,note TEXT)");d.execSQL("INSERT OR IGNORE INTO material_products(name,currentPrice,active) VALUES('TİŞÖRT',500,1)");}
    private void createSyncTables(SQLiteDatabase d){d.execSQL("CREATE TABLE IF NOT EXISTS sync_state(entity TEXT NOT NULL,entityKey TEXT NOT NULL,cloudUpdatedAt TEXT,localHash TEXT,lastSyncedAt INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(entity,entityKey))");}
    private void createRecentPayments(SQLiteDatabase d){d.execSQL("CREATE TABLE IF NOT EXISTS payment_recent(athleteId INTEGER NOT NULL,year INTEGER NOT NULL,month INTEGER NOT NULL,amount INTEGER NOT NULL,savedAt INTEGER NOT NULL,PRIMARY KEY(athleteId,year,month))");}
    private void createRestartPeriods(SQLiteDatabase d){d.execSQL("CREATE TABLE IF NOT EXISTS athlete_restart_periods(athleteId INTEGER PRIMARY KEY,restartEndDate TEXT NOT NULL DEFAULT '')");}
    private boolean hasColumn(SQLiteDatabase d,String table,String col){Cursor c=null;try{c=d.rawQuery("PRAGMA table_info("+table+")",null);while(c.moveToNext())if(col.equalsIgnoreCase(c.getString(c.getColumnIndexOrThrow("name"))))return true;}catch(Exception ignored){}finally{if(c!=null)c.close();}return false;}
    private void addColumn(SQLiteDatabase d,String table,String col,String type){try{if(!hasColumn(d,table,col))d.execSQL("ALTER TABLE "+table+" ADD COLUMN "+col+" "+type);}catch(Exception ignored){}}

    @Override public void onUpgrade(SQLiteDatabase d,int oldVersion,int newVersion){createFeeHistory(d);addColumn(d,"athletes","birthDate","TEXT");addColumn(d,"athletes","tckn","TEXT");addColumn(d,"athletes","summerCall","INTEGER NOT NULL DEFAULT 0");addColumn(d,"athletes","winterCall","INTEGER NOT NULL DEFAULT 0");addColumn(d,"athletes","deletedAt","TEXT");addColumn(d,"athletes","deletedPrevStatus","TEXT");createMaterialTables(d);createSyncTables(d);createRecentPayments(d);createRestartPeriods(d);}

    public String restartEndDate(long athleteId){SQLiteDatabase d=getReadableDatabase();createRestartPeriods(d);Cursor c=d.rawQuery("SELECT restartEndDate FROM athlete_restart_periods WHERE athleteId=?",new String[]{String.valueOf(athleteId)});String s="";if(c.moveToFirst()&&!c.isNull(0))s=c.getString(0);c.close();return s==null?"":s;}
    public void setRestartEndDate(long athleteId,String date){SQLiteDatabase d=getWritableDatabase();createRestartPeriods(d);String x=date==null?"":date.trim();if(x.isEmpty()){d.delete("athlete_restart_periods","athleteId=?",new String[]{String.valueOf(athleteId)});return;}ContentValues v=new ContentValues();v.put("athleteId",athleteId);v.put("restartEndDate",x);d.insertWithOnConflict("athlete_restart_periods",null,v,SQLiteDatabase.CONFLICT_REPLACE);}

    private Context getContext(){return ctx;}
    @Override public SQLiteDatabase getWritableDatabase(){return super.getWritableDatabase();}
    public Cursor athletes(String q,String status){String sql="SELECT * FROM athletes WHERE TRIM(COALESCE(deletedAt,''))=''";ArrayList<String> args=new ArrayList<>();if(q!=null&&!q.trim().isEmpty()){sql+=" AND name LIKE ?";args.add("%"+q.trim().toUpperCase(Locale.forLanguageTag("tr-TR"))+"%");}if(status!=null&&!status.equals("TÜMÜ")){sql+=" AND status=?";args.add(status);}sql+=" ORDER BY CASE status WHEN 'AKTİF' THEN 0 WHEN 'ARA VERDİ' THEN 1 ELSE 2 END,name COLLATE NOCASE";return getReadableDatabase().rawQuery(sql,args.toArray(new String[0]));}
    public Cursor athlete(long id){return getReadableDatabase().rawQuery("SELECT * FROM athletes WHERE id=?",new String[]{String.valueOf(id)});}
    public Cursor payments(long id){return getReadableDatabase().rawQuery("SELECT * FROM payments WHERE athleteId=? ORDER BY year,month",new String[]{String.valueOf(id)});}
    public Cursor recentPayments(int limit){SQLiteDatabase d=getReadableDatabase();createRecentPayments(d);return d.rawQuery("SELECT r.athleteId,r.year,r.month,r.amount,r.savedAt,a.name FROM payment_recent r JOIN athletes a ON a.id=r.athleteId WHERE r.amount>0 ORDER BY r.savedAt DESC LIMIT ?",new String[]{String.valueOf(limit)});}
    public int count(String status){Cursor c=getReadableDatabase().rawQuery(status==null?"SELECT COUNT(*) FROM athletes WHERE TRIM(COALESCE(deletedAt,''))=''":"SELECT COUNT(*) FROM athletes WHERE TRIM(COALESCE(deletedAt,''))='' AND status=?",status==null?null:new String[]{status});c.moveToFirst();int x=c.getInt(0);c.close();return x;}
    public int paidThisMonth(int year,int month){Cursor c=getReadableDatabase().rawQuery("SELECT COALESCE(SUM(amount),0) FROM payments WHERE year=? AND month=?",new String[]{String.valueOf(year),String.valueOf(month)});c.moveToFirst();int x=c.getInt(0);c.close();return x;}
    public void updatePayment(long athleteId,int month,String marker,int amount){SQLiteDatabase d=getWritableDatabase();ContentValues v=new ContentValues();v.put("athleteId",athleteId);v.put("year",2026);v.put("month",month);v.put("marker",marker);v.put("amount",amount);d.insertWithOnConflict("payments",null,v,SQLiteDatabase.CONFLICT_REPLACE);createRecentPayments(d);boolean paid=amount>0&&(isDateMarker(marker)||"!".equals(marker)||"!!".equals(marker));if(paid){ContentValues r=new ContentValues();r.put("athleteId",athleteId);r.put("year",2026);r.put("month",month);r.put("amount",amount);r.put("savedAt",System.currentTimeMillis());d.insertWithOnConflict("payment_recent",null,r,SQLiteDatabase.CONFLICT_REPLACE);}else d.delete("payment_recent","athleteId=? AND year=2026 AND month=?",new String[]{String.valueOf(athleteId),String.valueOf(month)});}

    public ArrayList<String> uniqueNotes(){ArrayList<String> x=new ArrayList<>();Cursor c=getReadableDatabase().rawQuery("SELECT DISTINCT TRIM(notes) n FROM athletes WHERE TRIM(COALESCE(notes,''))<>'' AND TRIM(COALESCE(deletedAt,''))='' ORDER BY n COLLATE NOCASE",null);while(c.moveToNext())x.add(c.getString(0));c.close();return x;}
    public void setFeeFromMonth(long athleteId,int month,int fee){ContentValues v=new ContentValues();v.put("athleteId",athleteId);v.put("year",2026);v.put("effectiveMonth",month);v.put("fee",fee);getWritableDatabase().insertWithOnConflict("fee_history",null,v,SQLiteDatabase.CONFLICT_REPLACE);Calendar now=Calendar.getInstance();if(now.get(Calendar.YEAR)>2026 || (now.get(Calendar.YEAR)==2026 && month<=now.get(Calendar.MONTH)+1)){ContentValues a=new ContentValues();a.put("monthlyFee",fee);getWritableDatabase().update("athletes",a,"id=?",new String[]{String.valueOf(athleteId)});}}
    public int expectedFee(long athleteId,int month){SQLiteDatabase d=getReadableDatabase();Cursor h=d.rawQuery("SELECT fee FROM fee_history WHERE athleteId=? AND year=2026 AND effectiveMonth<=? ORDER BY effectiveMonth DESC LIMIT 1",new String[]{String.valueOf(athleteId),String.valueOf(month)});if(h.moveToFirst()){int f=h.getInt(0);h.close();return f;}h.close();int current=0;Cursor a=d.rawQuery("SELECT monthlyFee,sibling FROM athletes WHERE id=?",new String[]{String.valueOf(athleteId)});String sibling="";if(a.moveToFirst()){current=a.getInt(0);sibling=a.getString(1)==null?"":a.getString(1);}a.close();if("BURSLU".equalsIgnoreCase(sibling)||current==0)return 0;Cursor t=d.rawQuery("SELECT marker,amount FROM payments WHERE athleteId=? AND year=2026 AND month=?",new String[]{String.valueOf(athleteId),String.valueOf(month)});if(t.moveToFirst()){String mk=t.getString(0)==null?"":t.getString(0);int amt=t.getInt(1);if(isDateMarker(mk)&&amt>0){t.close();return amt;}}t.close();int prev=normalAmount(d,athleteId,month,-1), next=normalAmount(d,athleteId,month,1);Cursor mark=d.rawQuery("SELECT marker FROM payments WHERE athleteId=? AND year=2026 AND month=?",new String[]{String.valueOf(athleteId),String.valueOf(month)});String mk="";if(mark.moveToFirst())mk=mark.getString(0)==null?"":mark.getString(0);mark.close();if("!".equals(mk)||"!!".equals(mk)){if(prev>0&&next>0){if(prev==next)return prev;if(next==current)return next;return prev;}if(next>0)return next;if(prev>0)return prev;return current;}Calendar now=Calendar.getInstance();if(now.get(Calendar.YEAR)==2026 && month>=now.get(Calendar.MONTH)+1 && current>0 && prev>0 && prev!=current)return current;if(prev>0)return prev;if(next>0)return next;return current;}
    private int normalAmount(SQLiteDatabase d,long athleteId,int month,int dir){for(int m=month+dir;m>=1&&m<=12;m+=dir){Cursor c=d.rawQuery("SELECT marker,amount FROM payments WHERE athleteId=? AND year=2026 AND month=?",new String[]{String.valueOf(athleteId),String.valueOf(m)});if(c.moveToFirst()){String mk=c.getString(0)==null?"":c.getString(0);int amt=c.getInt(1);c.close();if(isDateMarker(mk)&&amt>0)return amt;}else c.close();}return 0;}
    private boolean isDateMarker(String x){return x!=null&&x.matches("\\d{4}-\\d{2}-\\d{2}");}
}
